"""A dome pushed against the top edge still counts as our fort camp.

Owner 2026-11-15: 砦になったキャンプはまだ無視されている. The dome needs a full
flag in the old rule, so a clipped one was never recalled.
"""
from docich.hanjuku_speedrun.hanjuku.os_layer.pixels import Frame
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import CAMP_FLAG, DOME_BODY, DOME_DOOR, DOME_OUTLINE, _dome_camps

BODY, SHADOW, LIGHT = DOME_BODY


def dome_frame(*, flag=True):
    width, height = 256, 224
    pixels = bytearray(width * height * 3)

    def put(x, y, colour):
        index = (y * width + x) * 3
        pixels[index:index + 3] = bytes(colour)

    # The door (6-24 px), the body band above it and the dark outline.
    for y in range(20, 24):
        for x in range(100, 103):
            put(x, y, DOME_DOOR)
    for y in range(16, 20):
        for x in range(98, 106):
            put(x, y, BODY if x < 102 else SHADOW)
    for x in range(97, 108):
        put(x, 15, DOME_OUTLINE)
        put(x, 24, DOME_OUTLINE)
    for y in range(15, 25):
        put(97, y, DOME_OUTLINE)
        put(107, y, DOME_OUTLINE)
    if flag:
        for x in range(101, 104):
            put(x, 8, CAMP_FLAG)
            put(x, 9, (238, 113, 57))
    return Frame(width, height, bytes(pixels))


def test_a_clipped_dome_is_found_and_marked_clipped():
    camps = _dome_camps(dome_frame(flag=False))
    assert camps and camps[0]['clipped'] is True and camps[0]['kind'] == 'dome'


def test_a_full_dome_keeps_its_flag_target():
    camps = _dome_camps(dome_frame(flag=True))
    assert camps and camps[0]['clipped'] is False
